contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        // give C some pre-existing dust so the rule covers total balance, not just msg.value
        uint dust = 1 wei;
        c.go{value: dust}();
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance == balanceBefore);
        }
    }
    receive() external payable {}
    fallback() external payable {}
}

