contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedBalance) public payable {
        require(seedBalance <= address(this).balance);
        // Fund C with a prior balance via its payable fallback.
        if (seedBalance > 0) {
            (bool ok, ) = address(c).call{value: seedBalance}("");
            require(ok);
        }
        uint256 priorC = address(c).balance;
        require(priorC == seedBalance);
        uint256 ownerBefore = address(this).balance;
        bool reverted;
        try c.go{value: 0}() { reverted = false; } catch { reverted = true; }
        if (reverted) {
            assert(address(this).balance == ownerBefore && address(c).balance == priorC);
        } else {
            assert(address(this).balance == ownerBefore + priorC && address(c).balance == 0);
        }
    }
    receive() external payable {}
    fallback() external payable {}
}

